import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const PRODUCTS = [
  { id: 1, name: "Утасгүй чихэвч", price: "159,000₮" },
  { id: 2, name: "Гар цаг X100", price: "249,000₮" },
];

function App() {
  const [screen, setScreen] = useState("list");
  const [selected, setSelected] = useState(null);

  if (screen === "detail") {
    return (
      <View style={styles.screen}>
        <Text nativeID="dname" style={styles.h}>{selected ? selected.name : ""}</Text>
        <Text>{selected ? selected.price : ""}</Text>
        <Pressable nativeID="back" style={styles.btn} onPress={() => setScreen("list")}>
          <Text style={styles.btnText}>← Буцах</Text>
        </Pressable>
      </View>
    );
  }
  return (
    <View style={styles.screen}>
      {PRODUCTS.map((p) => (
        <Pressable key={p.id} nativeID={"p" + p.id} style={styles.row}
          onPress={() => { setScreen("detail"); /* энд бичнэ үү: сонгосон барааг хадгал */ }}>
          <Text style={styles.name}>{p.name}</Text>
        </Pressable>
      ))}
    </View>
  );
}

const styles = StyleSheet.create({
  screen: { flex: 1, padding: 24, gap: 12, justifyContent: "center" },
  h: { fontSize: 24, fontWeight: "bold" },
  row: { backgroundColor: "#f1f5f9", padding: 16, borderRadius: 12 },
  name: { fontSize: 16, fontWeight: "600" },
  btn: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12, alignItems: "center" },
  btnText: { color: "#fff", fontWeight: "bold" },
});

registerRootComponent(App);

